function SubmitPage() {
  const [submitted, setSubmitted] = useState(false);
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setSubmitted(true); };
  return <Layout><PageHero eyebrow="Call for contributions" title="Abstract submission guidelines" body="Stream Conferences invites researchers, clinicians, academicians, and industry leaders to submit original abstracts for oral, poster, and virtual presentations. Every submission receives rigorous double-blind peer review." /><main><section className="section-pad"><div className="container-wide"><div className="grid gap-10 lg:grid-cols-[1.1fr_.9fr]"><div><SectionTitle eyebrow="01 · Important dates" title="Give the work a clear runway." body="Dates shown in brackets are placeholders to be confirmed by the secretariat." /><div className="mt-10 grid gap-3">{[['[Date]', 'Early-bird abstract submission deadline'], ['[Date]', 'Final abstract submission deadline'], ['5–7 business days', 'Notification of acceptance'], ['[Date]', 'Presenter registration deadline']].map(([date, title], i) => <div key={title} className="flex gap-5 border-b border-[hsl(var(--border))] py-5" data-testid={`submission-date-${i}`}><span className="display text-xl font-bold text-[hsl(var(--accent))]">0{i + 1}</span><div><p className="font-bold">{title}</p><p className="mt-1 text-sm text-[hsl(var(--secondary))]">{date}</p></div></div>)}</div></div><div className="rounded-2xl bg-[hsl(var(--primary))] p-7 text-[hsl(var(--primary-foreground))]"><p className="label text-[hsl(var(--accent))]">Start here</p><h3 className="display mt-4 text-3xl font-bold">Have original work ready?</h3><p className="mt-4 text-sm leading-7 text-[hsl(var(--primary-foreground)/.7)]">Prepare your structured abstract, choose a track and format, then send it to the scientific coordination desk.</p><a href="mailto:abstracts@streamconferences.com" className="btn-main btn-primary mt-7" data-testid="link-email-abstracts">Email the abstract desk <Send size={16} /></a><p className="mt-4 text-xs text-[hsl(var(--primary-foreground)/.5)]">Template download and portal links are placeholders until launch.</p></div></div></div></section><section className="section-pad bg-[hsl(var(--muted)/.35)]"><div className="container-wide"><SectionTitle eyebrow="02 · Categories & formats" title="Choose the right room for the work." /><TrackGrid /><div className="mt-16 grid gap-4 md:grid-cols-4">{[['Keynote / Plenary Talk', 'Distinguished speakers and senior authorities · 25–30 minutes'], ['Oral Presentation', 'Standard research presentation · 15–20 minutes including Q&A'], ['Poster Presentation', 'Visual display with dedicated live interactive Q&A'], ['Virtual / Online', 'Recorded or live-streamed presentation for remote delegates']].map(([title, text], i) => <div key={title} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5" data-testid={`card-format-${i}`}><span className="label text-[hsl(var(--accent))]">0{i + 1}</span><h3 className="display mt-9 text-lg font-bold">{title}</h3><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{text}</p></div>)}</div></div></section><section className="section-pad"><div className="container-wide grid gap-12 lg:grid-cols-[1.1fr_.9fr]"><div><SectionTitle eyebrow="03 · Formatting requirements" title="A compact brief. A rigorous structure." /><div className="mt-8 grid gap-3">{[['Title', 'Maximum 25 words. Concise, descriptive, Title Case.'], ['Author details', 'Full names, affiliations, city, country, and email. Mark presenting author with *.'], ['Word limit', '250–350 words, excluding title, authors, and affiliations.'], ['Keywords', '3–6 relevant keywords, separated by semicolons.'], ['Core structure', 'Background / Objectives · Methods · Results / Findings · Conclusion / Significance.']].map(([key, value]) => <div key={key} className="border-l-2 border-[hsl(var(--accent))] py-2 pl-5"><p className="font-bold">{key}</p><p className="mt-1 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{value}</p></div>)}</div></div><div><SectionTitle eyebrow="04 · How to submit" title="Four steps to a submission ID." /><ol className="mt-8 grid gap-4">{['Prepare your abstract using the standard Stream Conferences Abstract Template (.docx).', 'Access the online submission portal via the Submit Abstract button.', 'Fill out author information, track, and presentation format.', 'Upload your document and receive an automated confirmation email.'].map((step, i) => <li key={step} className="flex gap-4"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-[hsl(var(--secondary))] text-sm font-bold text-[hsl(var(--secondary-foreground))]">{i + 1}</span><p className="pt-1 text-sm leading-6">{step}</p></li>)}</ol><button type="button" onClick={() => window.alert('Template download placeholder — replace with the final .docx file.')} className="btn-main btn-quiet mt-7" data-testid="button-download-template"><Download size={16} /> Download template</button></div></div></section><section className="section-pad bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]"><div className="container-wide grid gap-12 lg:grid-cols-[.85fr_1.15fr]"><div><SectionTitle light eyebrow="05 · Your submission" title="Put the work in motion." body="Mock submission handling is enabled for this preview. Replace with the final portal connection before launch." /></div>{submitted ? <SuccessState title="Submission received" body="Thank you. A confirmation with your placeholder Submission ID will be sent to the email provided." reset={() => setSubmitted(false)} testId="status-abstract-success" /> : <form onSubmit={submit} className="grid gap-4 rounded-2xl border border-[hsl(var(--primary-foreground)/.17)] bg-[hsl(var(--primary-foreground)/.06)] p-6" aria-label="Abstract submission form"><input required className="form-field" placeholder="Full name" aria-label="Full name" data-testid="input-abstract-name" /><input required type="email" className="form-field" placeholder="Email address" aria-label="Email address" data-testid="input-abstract-email" /><select className="form-field" defaultValue="" aria-label="Track" data-testid="select-abstract-track"><option value="" disabled>Select primary track</option>{tracks.map((track) => <option key={track.title}>{track.title}</option>)}</select><textarea required className="form-field min-h-28" placeholder="Abstract title and a short summary" aria-label="Abstract summary" data-testid="input-abstract-summary" /><button className="btn-main btn-primary mt-2" type="submit" data-testid="button-submit-abstract">Send for review <ArrowUpRight size={16} /></button><p className="text-xs text-[hsl(var(--primary-foreground)/.5)]">By submitting, you confirm the work is original and ethically compliant.</p></form>}</div></section></main></Layout>;
}

function SuccessState({ title, body, reset, testId }: { title: string; body: string; reset?: () => void; testId: string }) {
  return <div className="flex flex-col justify-center rounded-2xl border border-[hsl(var(--accent)/.4)] bg-[hsl(var(--accent)/.1)] p-8" data-testid={testId}><div className="grid h-12 w-12 place-items-center rounded-full bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><Check size={24} /></div><h3 className="display mt-6 text-3xl font-bold">{title}</h3><p className="mt-3 max-w-md text-sm leading-7 text-[hsl(var(--primary-foreground)/.7)]">{body}</p>{reset && <button type="button" onClick={reset} className="mt-7 self-start text-sm font-bold text-[hsl(var(--accent))]" data-testid="button-reset-form">Submit another response</button>}</div>;
}

