function FAQPage() {
  const [open, setOpen] = useState<number | null>(0);
  const [query, setQuery] = useState('');
  const filtered = useMemo(() => faqs.filter(([question, answer]) => `${question} ${answer}`.toLowerCase().includes(query.toLowerCase())), [query]);
  return <Layout><PageHero eyebrow="Delegate desk" title="The questions worth answering early." body="Find practical guidance on eligibility, submission, review, presentation formats, registration, and joining from abroad." /><main className="section-pad"><div className="container-wide max-w-4xl"><div className="relative mb-10"><Search className="absolute left-4 top-3.5 text-[hsl(var(--muted-foreground))]" size={18} /><input className="form-field pl-11" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search the delegate desk" aria-label="Search FAQs" data-testid="input-faq-search" /></div><div className="grid gap-3">{filtered.map(([question, answer], index) => { const actualIndex = faqs.findIndex(([item]) => item === question); const isOpen = open === actualIndex; return <div key={question} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><button type="button" onClick={() => setOpen(isOpen ? null : actualIndex)} className="flex w-full items-center justify-between gap-5 p-5 text-left font-bold" aria-expanded={isOpen} data-testid={`button-faq-${actualIndex}`}><span>{question}</span><ChevronDown size={18} className={`shrink-0 text-[hsl(var(--secondary))] transition-transform ${isOpen ? 'rotate-180' : ''}`} /></button>{isOpen && <div className="border-t border-[hsl(var(--border))] px-5 pb-5 pt-4 text-sm leading-7 text-[hsl(var(--muted-foreground))]" data-testid={`text-faq-answer-${actualIndex}`}>{answer}</div>}</div>; })}</div>{filtered.length === 0 && <div className="rounded-2xl border border-dashed border-[hsl(var(--border))] p-10 text-center"><CircleHelp className="mx-auto text-[hsl(var(--secondary))]" /><p className="mt-4 font-bold">No matching questions</p><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Try a shorter search, or email the scientific coordination team.</p></div>}<div className="mt-16 rounded-2xl bg-[hsl(var(--muted))] p-7"><p className="label text-[hsl(var(--secondary))]">Need further assistance?</p><p className="mt-3 max-w-2xl text-sm leading-7">For questions regarding abstract guidelines or technical issues, contact <a href="mailto:abstracts@streamconferences.com" className="font-bold text-[hsl(var(--secondary))]" data-testid="link-faq-email">abstracts@streamconferences.com</a>.</p><Link href="/contact" className="btn-main btn-quiet mt-6" data-testid="link-faq-contact">Contact us <ArrowUpRight size={16} /></Link></div></div></main></Layout>;
}

function GuidelinesPage() {
  const sections = [['Presentation day checklist', ['Arrive 30 minutes before your session.', 'Check in at the speaker desk and confirm your file.', 'Keep a backup copy on a USB drive and in cloud storage.', 'Stay for questions and support the presenters after you.']], ['Poster specifications · placeholder', ['A0 or A1 portrait orientation.', 'Export at print-ready resolution with accessible type sizes.', 'Include title, authors, affiliations, methods, results, and contact.', 'Final dimensions and mounting instructions to be confirmed.']], ['AV & room support', ['HDMI presentation connection and confidence monitor.', 'Session chair, handheld microphone, and venue Wi-Fi.', 'Technical rehearsal windows published in the final program.', 'Tell the speaker desk about accessibility requirements early.']], ['Code of conduct', ['Be generous with questions and precise with critique.', 'Respect consent, privacy, and intellectual property.', 'No harassment, discrimination, or commercial promotion.', 'Raise concerns with the organizing committee promptly.']]];
  return <Layout><PageHero eyebrow="Practical notes" title="Arrive ready to contribute." body="A short field guide for presenters and delegates. Specifications marked placeholder will be replaced with the final venue and production plan." /><main className="section-pad"><div className="container-wide grid gap-4 md:grid-cols-2">{sections.map(([title, items], i) => <div key={String(title)} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-7" data-testid={`card-guideline-${i}`}><span className="label text-[hsl(var(--accent))]">0{i + 1}</span><h2 className="display mt-7 text-2xl font-bold">{title}</h2><ul className="mt-6 grid gap-3">{(items as string[]).map((item) => <li key={item} className="flex gap-3 text-sm leading-6"><Check size={16} className="mt-1 shrink-0 text-[hsl(var(--secondary))]" />{item}</li>)}</ul></div>)}</div></main></Layout>;
}

function TermsPage() {
  const sections = [['Registration & payment terms', 'Registration rates, inclusions, taxes, and payment processing details are illustrative placeholders and must be reviewed and replaced by Stream Conferences before publication. A registration is confirmed only after successful payment and written confirmation.'], ['Cancellation & refund policy', 'Sample policy for legal review: cancellation requests must be made in writing. Refund windows, administrative fees, and transfer options will be published with the final registration terms.'], ['Abstract & publication rights', 'Authors retain ownership of their work while granting the conference a non-exclusive right to display accepted material in conference materials and official digital proceedings. DOI and ISBN assignment are subject to editorial review.'], ['Code of conduct', 'All delegates are expected to participate with respect, integrity, and professional care. Harassment, discrimination, intimidation, and unauthorized commercial promotion are not permitted.'], ['Liability', 'Sample text for legal review: attendees participate at their own risk. The organizers are not responsible for loss, travel disruption, or personal injury beyond the protections required by applicable law.'], ['Force majeure', 'If circumstances beyond reasonable control affect the event, the organizers may reschedule, change format, or cancel the event. Final remedies and notices will be defined in the reviewed policy.']];
  return <Layout><PageHero eyebrow="The fine print" title="Terms & conditions." body="Sample conference terms for review by Stream Conferences legal counsel. This page is intentionally marked as placeholder content." /><main className="section-pad"><div className="container-wide max-w-4xl"><div className="mb-10 rounded-2xl border border-[hsl(var(--accent)/.5)] bg-[hsl(var(--accent)/.12)] p-5 text-sm leading-6"><ShieldCheck className="mr-2 inline text-[hsl(var(--secondary))]" size={18} /> Sample legal copy · Replace and approve with counsel before launch.</div><div className="grid gap-8">{sections.map(([title, text], i) => <section key={title} className="border-b border-[hsl(var(--border))] pb-8"><p className="label text-[hsl(var(--secondary))]">0{i + 1}</p><h2 className="display mt-3 text-2xl font-bold">{title}</h2><p className="mt-4 text-sm leading-8 text-[hsl(var(--muted-foreground))]">{text}</p></section>)}</div></div></main></Layout>;
}

function ContactPage() {
  const [sent, setSent] = useState(false);
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setSent(true); };
  const departments = [['General & Delegate Inquiries', 'info@streamconferences.com', 'Upcoming events, registration, and general information.'], ['Abstract Submissions & Speaker Desk', 'abstracts@streamconferences.com', 'Abstract guidelines, status, formats, and reviews.'], ['Publishing & Research Indexing', 'publishing@streamconferences.com', 'Proceedings, DOI assignments, and journal partnerships.'], ['Sponsorships & Strategic Partnerships', 'partners@streamconferences.com', 'Sponsorship and exhibit opportunities.']];
  return <Layout><PageHero eyebrow="The secretariat" title="Get in touch with Stream Conferences." body="Whether you are presenting groundbreaking research, planning attendance, exploring publishing, or discussing sponsorship, our team is here to assist. We aim to respond within 24–48 business hours." /><main><section className="section-pad"><div className="container-wide"><div className="grid gap-4 md:grid-cols-2">{departments.map(([title, email, body], i) => <div key={email} className="card-lift rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6" data-testid={`card-contact-${i}`}><Mail className="text-[hsl(var(--secondary))]" size={21} /><h2 className="display mt-6 text-xl font-bold">{title}</h2><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{body}</p><a href={`mailto:${email}`} className="mt-5 inline-block text-sm font-bold text-[hsl(var(--secondary))]" data-testid={`link-contact-email-${i}`}>{email}</a></div>)}</div></div></section><section className="section-pad bg-[hsl(var(--muted)/.35)]"><div className="container-wide grid gap-12 lg:grid-cols-[.7fr_1.3fr]"><div><SectionTitle eyebrow="Global headquarters" title="A team with a reachable desk." body="Stream Conferences · [Insert Business Address / Building Name] · [Insert City, State/Province, Country, Postal Code]" /><div className="mt-7 grid gap-3 text-sm"><p className="flex items-center gap-3"><Phone size={17} className="text-[hsl(var(--secondary))]" /> +1 [Insert Phone Number]</p><p className="flex items-center gap-3"><Clock3 size={17} className="text-[hsl(var(--secondary))]" /> Monday–Friday · 9:00 AM–6:00 PM EST</p></div></div>{sent ? <SuccessState title="Message sent" body="Thank you. Our coordination team will respond within 24–48 business hours." reset={() => setSent(false)} testId="status-contact-success" /> : <form onSubmit={submit} className="grid gap-4 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="grid gap-4 sm:grid-cols-2"><input required className="form-field" placeholder="Full name" aria-label="Full name" data-testid="input-contact-name" /><input required type="email" className="form-field" placeholder="Email address" aria-label="Email address" data-testid="input-contact-email" /></div><input className="form-field" placeholder="Phone number" aria-label="Phone number" data-testid="input-contact-phone" /><select className="form-field" defaultValue="General" aria-label="Inquiry type" data-testid="select-contact-inquiry"><option>General</option><option>Abstract Submission</option><option>Publishing</option><option>Sponsorship</option></select><input className="form-field" defaultValue={conferenceName} aria-label="Conference name" data-testid="input-contact-conference" /><textarea required className="form-field min-h-32" placeholder="How can we help?" aria-label="Message" data-testid="input-contact-message" /><button type="submit" className="btn-main btn-primary" data-testid="button-submit-contact">Send us a message <Send size={16} /></button></form>}</div></section></main></Layout>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>;
}

function Router() {
  return <RoutedErrorBoundary><Switch><Route path="/" component={Home} /><Route path="/about" component={AboutPage} /><Route path="/submit-abstract" component={SubmitPage} /><Route path="/itinerary" component={ItineraryPage} /><Route path="/program" component={ProgramPage} /><Route path="/speakers" component={SpeakersPage} /><Route path="/gallery" component={GalleryPage} /><Route path="/past-conferences" component={PastConferencesPage} /><Route path="/brochure" component={BrochurePage} /><Route path="/venue" component={VenuePage} /><Route path="/sponsors" component={SponsorsPage} /><Route path="/register" component={RegisterPage} /><Route path="/terms" component={TermsPage} /><Route path="/faq" component={FAQPage} /><Route path="/guidelines" component={GuidelinesPage} /><Route path="/contact" component={ContactPage} /><Route component={NotFound} /></Switch></RoutedErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;